#pragma once

/* ARCH-52: trait of the synthetic driver (module.yaml binding.trait ::synth::SynthBinding) - the few C++-specific
 * lines of its integration, written by the module author next to the driver and checked by the compiler. Everything
 * else (the objects per instance, the lifecycle registration in level and task of the manifest, the safe_off
 * adapters, the RTE reader) is generated by tools/bswgen (integration/moduleBinding.h); the family port only provides
 * its binders per connection kind and contract (ModuleBinders.h). Contract: tools/bswgen/modules.py, section
 * "binding (ARCH-52)". */

#include "synth/SynthDriver.h"

#include <async/Types.h>
#include <etl/alignment.h>
#include <spi/ISpiDevice.h>

#include <cstdint>

namespace synth
{
namespace detail
{
constexpr bool equal(char const* a, char const* b)
{
    while ((*a != '\0') && (*a == *b))
    {
        ++a;
        ++b;
    }
    return *a == *b;
}
} // namespace detail

struct SynthBinding
{
    using System = SynthSystem;

    // Device facts for the SPI binder of the family (contract spi_device): 16-bit frames, SPI mode 1
    static constexpr uint8_t SPI_FRAME_BITS  = 16U;
    static constexpr bool SPI_CPOL           = false;
    static constexpr bool SPI_CPHA           = true;
    static constexpr uint32_t SPI_MAX_HZ     = 2000000UL;
    static constexpr uint32_t SPI_TIMEOUT_US = 1000UL;
    // Longest label of the log lines of this driver
    static constexpr uint32_t LABEL_MAX_CHARS = 16U;

    /** Configuration of instance I (generated description: I::Param in the units of the manifest). */
    template<class I>
    static constexpr Config config()
    {
        return Config{I::Param::CYCLE_MS, I::Param::OFFSET_C, detail::equal(I::Param::MODE, "fast")};
    }

    static constexpr bool valid(Config const& c) { return isValidConfig(c); }

    /** Pins of instance I on the family binders B, and the SPI device the family binds for it. */
    template<class I, class B>
    class Parts : public ISynthIo
    {
    public:
        explicit Parts(::bsp::spi::ISpiDevice& spi) : _spi(spi) {}

        Parts(Parts const&)            = delete;
        Parts& operator=(Parts const&) = delete;

        bool setEnable(bool const on) override { return B::set(I::Connect::EN, on); }

        bool readFault(bool& active) override
        {
            if constexpr (I::Connect::FAULT_WIRED)
            {
                return B::get(I::Connect::FAULT, active);
            }
            else
            {
                active = false; // not wired on this board: never active
                return true;
            }
        }

        bool faultWired() const override { return I::Connect::FAULT_WIRED; }

        bool readSense(int32_t& value) override
        {
            uint16_t raw = 0U;
            if (!B::read(I::Connect::SENSE, raw))
            {
                return false;
            }
            uint8_t quality = 0U;
            value           = B::physical(I::Connect::SENSE, raw, quality);
            return true;
        }

        ::bsp::spi::ISpiDevice& spi() { return _spi; }

    private:
        ::bsp::spi::ISpiDevice& _spi;
    };

    template<class I, class B>
    static System&
    create(::etl::typed_storage<System>& storage, ::async::ContextType const context, Parts<I, B>& parts)
    {
        static_assert(
            (sizeof(I::LABEL) - 1U) <= LABEL_MAX_CHARS, "synthDriver: label longer than LABEL_MAX_CHARS (log lines)");
        return storage.create(context, parts.spi(), parts, config<I>(), I::COMPONENT, I::LABEL);
    }

    /** safe_off connection en: what off, an explicit enable and the lock of the safe state mean for this driver. */
    struct SafeOff_en
    {
        using System = SynthSystem;

        static void off(System& s) { s.driver().disable(); }

        static uint32_t enables(System const& s) { return s.driver().enables(); }

        static void setLock(System& s, SynthDriver::Lock const lock) { s.driver().setLock(lock); }

        static bool updateLock(System& s) { return s.driver().updateLock(); }
    };

    /** RTE reading of one instance (module.yaml rte, access reading); nullptr before the system is created. */
    static void rte(System const* const s, Reading& reading)
    {
        reading = (s == nullptr) ? Reading{0U, 1U} : s->driver().reading();
    }
};

} // namespace synth
